import{_ as a,o as e,c as r,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const _=JSON.parse('{"title":"镜像与自我","description":"","frontmatter":{"title":"镜像与自我","date":"2026-07-25T00:00:00.000Z","category":"thought","pinned":true,"pinOrder":2,"summary":"众镜相照，重重现影——关于认知、反射与存在的沉思。"},"headers":[],"relativePath":"posts/thought/mirror-and-self.md","filePath":"posts/thought/mirror-and-self.md","lastUpdated":null}'),s={name:"posts/thought/mirror-and-self.md"};function l(n,t,i,d,p,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="镜像与自我" tabindex="-1">镜像与自我 <a class="header-anchor" href="#镜像与自我" aria-label="Permalink to &quot;镜像与自我&quot;">​</a></h1><blockquote><p>你思故我在。</p></blockquote><p>当我们凝视镜子，看到的不仅是面容，更是自我认知的投射。每一面镜子都是一次反思的机会。</p><h2 id="多重镜像" tabindex="-1">多重镜像 <a class="header-anchor" href="#多重镜像" aria-label="Permalink to &quot;多重镜像&quot;">​</a></h2><p>想象无数面镜子环绕着你：</p><ol><li><strong>他者之镜</strong> — 他人眼中的你</li><li><strong>历史之镜</strong> — 过去的你映照现在的你</li><li><strong>理想之镜</strong> — 你渴望成为的样子</li></ol><p>众镜相照，重重现影，成其无尽复无尽。</p><h2 id="思与在" tabindex="-1">思与在 <a class="header-anchor" href="#思与在" aria-label="Permalink to &quot;思与在&quot;">​</a></h2><p>笛卡尔说「我思故我在」。但在众镜之间，「在」或许不只属于思者本身——你的思考在他人的镜像中得以延续和确认。</p><p>思，故我在；他思，故你亦在。</p>',10)])])}const u=a(s,[["render",l]]);export{_ as __pageData,u as default};
